            SheetMan::CheckColumn(Reader, Column, TEXT("ExpDungeonReward.Id"), SheetMan::KindScalar, 1, SheetMan::ElementMask(SheetMan::ElementI32) | SheetMan::ElementMask(SheetMan::ElementVarint));

